select * from ensino.matricula_componente where id_matricula_componente = 741807;

select string_agg(id_turma :: varchar, ', ') 
from ensino.turma where id_turma_serie  = (select id_turma_serie --string_agg(id_turma :: varchar, ', ') 
from ensino.turma where id_turma  = 738562); 

select * --string_agg(id_turma :: varchar, ', ') 
from ensino.turma where id_turma  = 738562; 

select * from ensino.frequencia_turma ft where ft.id_turma = 741813;

select * from ensino.frequencia_aluno fa where fa.id_turma =  739073 and fa.ativo = false order by data;

select * from ensino.horario_turma where id_turma in (739070) order by ATIVO, DATA_ALTERACAO

select * from ensino.horario_turma where id_turma in (738565) order by ATIVO, dia;

