select string_agg(id_horario_turma :: varchar, ', ')  from ensino.horario_turma where id_turma in (741861) and ativo = false and data_alteracao is null


BEGIN;

-- Passo 1: Criação da tabela temporária
CREATE TEMPORARY TABLE frequencias_para_consulta (id_frequencia BIGINT);

-- Passo 2: Inserção dos dados na tabela temporária
INSERT INTO frequencias_para_consulta (id_frequencia)
SELECT
    fa.id_frequencia
FROM
    (
        SELECT
            fa.*,
            ROW_NUMBER() OVER (
                PARTITION BY fa.id_discente, fa.id_turma, fa.data
                ORDER BY fa.data_atualizacao  DESC
            ) AS rn
        FROM
            ensino.frequencia_aluno fa
        WHERE
            NOT fa.ativo
            AND fa.id_turma IN (738562, 738563,738564, 738565, 738566, 738567,738568,738569, 738570)
            AND NOT EXISTS (
                SELECT 1
                FROM ensino.frequencia_aluno fa2
                WHERE
                    fa2.data = fa.data
                    AND fa2.id_discente = fa.id_discente
                    AND fa2.id_turma = fa.id_turma
                    AND fa2.ativo
            )
    ) AS fa
WHERE
    fa.rn = 1;

-- Passo 3: Geração do comando de backup
SELECT 'UPDATE ensino.frequencia_aluno SET ativo=false WHERE id_frequencia in (' || string_agg(id_frequencia::text, ', ') || ');' AS backup
FROM frequencias_para_consulta;

-- Passo 4: Solução final - Atualizar os registros para 'ativo=true'
UPDATE ensino.frequencia_aluno
SET ativo=true
WHERE id_frequencia IN (SELECT id_frequencia FROM frequencias_para_consulta);

--COMMIT;
--rollback;

